let uid = 0;
function Q(pkg, category, q, options, correct, source, opts = {}) {
  uid += 1;
  return {
    id: `${pkg}-${String(uid).padStart(3, "0")}`,
    pkg,
    category,
    q,
    options,
    correct,
    source,
    diagram: opts.diagram || null,
    note: opts.note || null,
  };
}

